const cp = require('child_process'); const fs = require('fs');
let fd = fs.openSync('/dev/zero', 'r'); let r = cp.spawnSync('head', ['-c', '300000'], { stdio: [fd, 'pipe', 'pipe'] }); fs.closeSync(fd);
console.log('spawnSync /dev/zero stdin', r.status, r.error && r.error.code, r.stdout && r.stdout.length);
fd = fs.openSync('/dev/null', 'w'); r = cp.spawnSync('head', ['-c', '5000000', '/dev/zero'], { stdio: ['ignore', fd, 'pipe'], maxBuffer: 10 }); fs.closeSync(fd);
console.log('spawnSync 5 MB to /dev/null', r.status, r.error && r.error.code);
fd = fs.openSync('/dev/null', 'r'); r = cp.spawnSync('wc', ['-c'], { stdio: [fd, 'pipe', 'pipe'] }); fs.closeSync(fd);
console.log('spawnSync /dev/null stdin', r.status, String(r.stdout).trim());
fd = fs.openSync('/dev/zero', 'r'); const c = cp.spawn('head', ['-c', '300000'], { stdio: [fd, 'pipe', 'inherit'] }); fs.closeSync(fd);
let n = 0; c.stdout.on('data', (d) => (n += d.length)); c.on('close', (code) => { console.log('spawn /dev/zero stdin, fd closed right after spawn', code, n);
  const fd2 = fs.openSync('/dev/null', 'w'); const c2 = cp.spawn('sh', ['-c', 'head -c 2000000 /dev/zero'], { stdio: ['ignore', fd2, 'inherit'] }); fs.closeSync(fd2); c2.on('close', (code2) => console.log('spawn to /dev/null, fd closed', code2)); });
